package items

import (
	"testing"
)

func TestGetItem_Found(t *testing.T) {
	item, err := GetItem(1)
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if item.Name != "Widget" {
		t.Errorf("expected Widget, got %s", item.Name)
	}
}

func TestGetItem_NotFound(t *testing.T) {
	_, err := GetItem(999)
	if err != ErrNotFound {
		t.Errorf("expected ErrNotFound, got %v", err)
	}
}

func TestParseID_Valid(t *testing.T) {
	id, err := ParseID("2")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if id != 2 {
		t.Errorf("expected 2, got %d", id)
	}
}

func TestParseID_NonNumeric(t *testing.T) {
	_, err := ParseID("abc")
	if err == nil {
		t.Error("expected error for non-numeric input")
	}
}

func TestParseID_Zero(t *testing.T) {
	_, err := ParseID("0")
	if err == nil {
		t.Error("expected error for id=0 (must be positive)")
	}
}

func TestParseID_Negative(t *testing.T) {
	_, err := ParseID("-1")
	if err == nil {
		t.Error("expected error for negative id")
	}
}

func TestDeleteItem_Existing(t *testing.T) {
	// Reset store to known state first
	store[99] = &Item{ID: 99, Name: "Temp"}
	err := DeleteItem(99)
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	_, err2 := GetItem(99)
	if err2 != ErrNotFound {
		t.Error("expected ErrNotFound after delete")
	}
}

func TestDeleteItem_NotFound(t *testing.T) {
	err := DeleteItem(9999)
	if err != ErrNotFound {
		t.Errorf("expected ErrNotFound, got %v", err)
	}
}
